-- C11 / P11.4 — versioned metadata, package manifests, pricing recommendations, and owner-locked rollout order.
create table if not exists public.command_center_book_metadata_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 metadata_event_id text not null check(btrim(metadata_event_id)<>''), metadata_id text not null check(btrim(metadata_id)<>''), project_id text not null check(btrim(project_id)<>''), book_id text not null check(btrim(book_id)<>''), version integer not null check(version>0), description text not null check(btrim(description)<>''), keywords text[] not null default '{}'::text[], categories text[] not null default '{}'::text[], trim_ref text not null check(btrim(trim_ref)<>''), bleed boolean not null, formats text[] not null check(cardinality(formats)>0), package_manifest_hash text not null check(btrim(package_manifest_hash)<>''), package_manifest_ref text not null check(btrim(package_manifest_ref)<>''), source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,metadata_event_id), unique(owner_id,book_id,version), check(formats <@ array['kindle','paperback','hardcover','digital_other','collection_kindle','collection_paperback','collection_hardcover']::text[])
);
create table if not exists public.command_center_book_rollout_plan_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 rollout_event_id text not null check(btrim(rollout_event_id)<>''), rollout_id text not null check(btrim(rollout_id)<>''), project_id text not null check(btrim(project_id)<>''), version integer not null check(version>0), owner_locked_order_ref text not null check(btrim(owner_locked_order_ref)<>''), source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,rollout_event_id), unique(owner_id,rollout_id,version)
);
create table if not exists public.command_center_book_rollout_step_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 step_event_id text not null check(btrim(step_event_id)<>''), rollout_id text not null check(btrim(rollout_id)<>''), rollout_version integer not null check(rollout_version>0), step_id text not null check(btrim(step_id)<>''), step_order integer not null check(step_order>0), phase integer not null check(phase>0), book_id text not null check(btrim(book_id)<>''), format text not null check(format in ('kindle','paperback','hardcover','digital_other','collection_kindle','collection_paperback','collection_hardcover')), kdp_select boolean not null, observed_at timestamptz not null,
 primary key(owner_id,step_event_id), unique(owner_id,rollout_id,rollout_version,step_id), unique(owner_id,rollout_id,rollout_version,step_order), check(kdp_select=false or format in ('kindle','collection_kindle'))
);
create table if not exists public.command_center_book_pricing_recommendation_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 pricing_event_id text not null check(btrim(pricing_event_id)<>''), pricing_id text not null check(btrim(pricing_id)<>''), project_id text not null check(btrim(project_id)<>''), book_id text not null check(btrim(book_id)<>''), format text not null check(format in ('kindle','paperback','hardcover','digital_other','collection_kindle','collection_paperback','collection_hardcover')), amount numeric not null check(amount>=0), currency text not null check(btrim(currency)<>''), confidence text not null check(confidence in ('confirmed','recommended')), rationale_refs text[] not null check(cardinality(rationale_refs)>0), source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,pricing_event_id), unique(owner_id,pricing_id)
);
create or replace view public.command_center_book_metadata_current with (security_invoker=true) as select distinct on(owner_id,book_id) owner_id,metadata_event_id,metadata_id,project_id,book_id,version,description,keywords,categories,trim_ref,bleed,formats,package_manifest_hash,package_manifest_ref,source_refs,observed_at from public.command_center_book_metadata_history order by owner_id,book_id,version desc,observed_at desc;
create or replace view public.command_center_book_rollout_plans_current with (security_invoker=true) as select distinct on(owner_id,rollout_id) owner_id,rollout_event_id,rollout_id,project_id,version,owner_locked_order_ref,source_refs,observed_at from public.command_center_book_rollout_plan_history order by owner_id,rollout_id,version desc,observed_at desc;
create or replace view public.command_center_book_pricing_current with (security_invoker=true) as select distinct on(owner_id,book_id,format) owner_id,pricing_event_id,pricing_id,project_id,book_id,format,amount,currency,confidence,rationale_refs,source_refs,observed_at from public.command_center_book_pricing_recommendation_history order by owner_id,book_id,format,observed_at desc;
create or replace function public.command_center_validate_book_rollout_step_insert() returns trigger language plpgsql set search_path to 'public' as $$ begin
 if not exists(select 1 from public.command_center_book_rollout_plan_history p where p.owner_id=new.owner_id and p.rollout_id=new.rollout_id and p.version=new.rollout_version) then raise exception 'Rollout step requires exact rollout plan version'; end if;
 if new.step_order>1 and not exists(select 1 from public.command_center_book_rollout_step_history s where s.owner_id=new.owner_id and s.rollout_id=new.rollout_id and s.rollout_version=new.rollout_version and s.step_order=new.step_order-1) then raise exception 'Rollout order must be contiguous and owner-locked'; end if;
 return new;
end $$;
drop trigger if exists command_center_book_rollout_step_validate on public.command_center_book_rollout_step_history; create trigger command_center_book_rollout_step_validate before insert on public.command_center_book_rollout_step_history for each row execute function public.command_center_validate_book_rollout_step_insert();
create or replace function public.command_center_reject_book_metadata_rollout_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Book metadata and rollout evidence is immutable'; end $$;
drop trigger if exists command_center_book_metadata_immutable on public.command_center_book_metadata_history; create trigger command_center_book_metadata_immutable before update or delete on public.command_center_book_metadata_history for each row execute function public.command_center_reject_book_metadata_rollout_mutation();
drop trigger if exists command_center_book_rollout_plan_immutable on public.command_center_book_rollout_plan_history; create trigger command_center_book_rollout_plan_immutable before update or delete on public.command_center_book_rollout_plan_history for each row execute function public.command_center_reject_book_metadata_rollout_mutation();
drop trigger if exists command_center_book_rollout_step_immutable on public.command_center_book_rollout_step_history; create trigger command_center_book_rollout_step_immutable before update or delete on public.command_center_book_rollout_step_history for each row execute function public.command_center_reject_book_metadata_rollout_mutation();
drop trigger if exists command_center_book_pricing_immutable on public.command_center_book_pricing_recommendation_history; create trigger command_center_book_pricing_immutable before update or delete on public.command_center_book_pricing_recommendation_history for each row execute function public.command_center_reject_book_metadata_rollout_mutation();
alter table public.command_center_book_metadata_history enable row level security; alter table public.command_center_book_rollout_plan_history enable row level security; alter table public.command_center_book_rollout_step_history enable row level security; alter table public.command_center_book_pricing_recommendation_history enable row level security;
revoke all on table public.command_center_book_metadata_history,public.command_center_book_rollout_plan_history,public.command_center_book_rollout_step_history,public.command_center_book_pricing_recommendation_history from public,anon,authenticated; grant select,insert on table public.command_center_book_metadata_history,public.command_center_book_rollout_plan_history,public.command_center_book_rollout_step_history,public.command_center_book_pricing_recommendation_history to authenticated; grant select on table public.command_center_book_metadata_current,public.command_center_book_rollout_plans_current,public.command_center_book_pricing_current to authenticated;
create policy p11_4_book_metadata_owner on public.command_center_book_metadata_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_4_book_rollout_plan_owner on public.command_center_book_rollout_plan_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_4_book_rollout_step_owner on public.command_center_book_rollout_step_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_4_book_pricing_owner on public.command_center_book_pricing_recommendation_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
